def longest_word_span(text):
    start = None
    best = None
    for index in range(len(text)+1):
        ch = text[index] if index < len(text) else " "
        if ch != " ":
            if start is None: start = index
        elif start is not None:
            if best is None or index-start > best[1]-best[0]:
                best = (start,index)
            start = None
    return best
