        if old is missing: mapping.pop(key,None)
        else: mapping[key]=old
@contextmanager
def temporary_many(mapping,pairs):
    with ExitStack() as stack:
        for key,value in pairs: stack.enter_context(one(mapping,key,value))
        yield mapping
