import re
def parse_lock(lines):
    result={}
    for line in lines:
        line=line.strip()
        if not line or line.startswith("#"): continue
        match=re.fullmatch(r"([A-Za-z0-9_-]+)==(\d+\.\d+\.\d+)",line)
