def solve(target, low=1, high=100):
    if type(target) is not int or not low <= target <= high:
        raise ValueError("目标不在区间中")
    trace = []
    while low <= high:
        guess = (low + high) // 2
        trace.append(guess)
        if guess == target:
            return trace
        if guess < target:
            low = guess + 1
        else:
            high = guess - 1
    raise AssertionError("有效目标不应丢失")
